import { addXp,createProgression } from './progression';
import type { PlayerCosmetics,PlayerProfile,PlayerSettings,PlayerStatistics } from './types';
export const defaultCosmetics=():PlayerCosmetics=>({ballId:'classic-white',trailId:'none',hatId:null,unlockedBallIds:['classic-white'],unlockedTrailIds:['none'],unlockedHatIds:[]});
export const defaultStatistics=():PlayerStatistics=>({matchesPlayed:0,matchesWon:0,holesPlayed:0,holesCompleted:0,totalStrokes:0,holesInOne:0,bestRoundStrokes:null,totalPlayTimeSeconds:0});
export const defaultSettings=():PlayerSettings=>({controlScheme:'drag',masterVolume:.8,musicVolume:.65,effectsVolume:.8,cameraSensitivity:1,invertCameraY:false,qualityPreset:'high',reducedMotion:false});
export function createDefaultProfile(now=new Date(),id='local-player'):PlayerProfile { const t=now.toISOString(); return {id,displayName:'Player',createdAt:t,updatedAt:t,progression:createProgression(),cosmetics:defaultCosmetics(),statistics:defaultStatistics(),settings:defaultSettings()}; }
export function awardPlayerXp(p:PlayerProfile,xp:number,now=new Date()):PlayerProfile { return {...p,progression:addXp(p.progression,xp),updatedAt:now.toISOString()}; }
