import { createDefaultProfile,defaultCosmetics,defaultSettings,defaultStatistics } from '../player/profile';
import { createProgression } from '../player/progression';
import type { PlayerProfile } from '../player/types';
export const SAVE_VERSION=2; export const DEFAULT_SAVE_KEY='crazy-putt-arena.save';
export interface StorageLike { getItem(k:string):string|null; setItem(k:string,v:string):void; removeItem(k:string):void }
type R=Record<string,unknown>; const rec=(v:unknown):v is R=>typeof v==='object'&&v!==null&&!Array.isArray(v); const num=(v:unknown,d=0)=>typeof v==='number'&&Number.isFinite(v)?v:d; const str=(v:unknown,d:string)=>typeof v==='string'&&v.length?v:d;
function normalize(v:unknown,f=createDefaultProfile()):PlayerProfile { if(!rec(v))return f; const p=rec(v.progression)?v.progression:{}; const c=rec(v.cosmetics)?v.cosmetics:{}; const s=rec(v.statistics)?v.statistics:{}; const o=rec(v.settings)?v.settings:{}; const dc=defaultCosmetics(),ds=defaultStatistics(),dset=defaultSettings(); const strings=(x:unknown,d:string[])=>Array.isArray(x)?[...new Set(x.filter((i):i is string=>typeof i==='string'))]:d; return {id:str(v.id,f.id),displayName:str(v.displayName,f.displayName).slice(0,32),createdAt:str(v.createdAt,f.createdAt),updatedAt:str(v.updatedAt,f.updatedAt),progression:createProgression(num(p.xp)),cosmetics:{ballId:str(c.ballId,dc.ballId),trailId:str(c.trailId,dc.trailId),hatId:typeof c.hatId==='string'?c.hatId:null,unlockedBallIds:strings(c.unlockedBallIds,dc.unlockedBallIds),unlockedTrailIds:strings(c.unlockedTrailIds,dc.unlockedTrailIds),unlockedHatIds:strings(c.unlockedHatIds,dc.unlockedHatIds)},statistics:{matchesPlayed:Math.max(0,Math.floor(num(s.matchesPlayed,ds.matchesPlayed))),matchesWon:Math.max(0,Math.floor(num(s.matchesWon,ds.matchesWon))),holesPlayed:Math.max(0,Math.floor(num(s.holesPlayed,ds.holesPlayed))),holesCompleted:Math.max(0,Math.floor(num(s.holesCompleted,ds.holesCompleted))),totalStrokes:Math.max(0,Math.floor(num(s.totalStrokes,ds.totalStrokes))),holesInOne:Math.max(0,Math.floor(num(s.holesInOne,ds.holesInOne))),bestRoundStrokes:s.bestRoundStrokes===null?null:Math.max(0,Math.floor(num(s.bestRoundStrokes,0))),totalPlayTimeSeconds:Math.max(0,Math.floor(num(s.totalPlayTimeSeconds,ds.totalPlayTimeSeconds)))},settings:{controlScheme:o.controlScheme==='charge'?'charge':'drag',masterVolume:Math.max(0,Math.min(1,num(o.masterVolume,dset.masterVolume))),musicVolume:Math.max(0,Math.min(1,num(o.musicVolume,dset.musicVolume))),effectsVolume:Math.max(0,Math.min(1,num(o.effectsVolume,dset.effectsVolume))),cameraSensitivity:Math.max(.1,Math.min(3,num(o.cameraSensitivity,dset.cameraSensitivity))),invertCameraY:o.invertCameraY===true,qualityPreset:o.qualityPreset==='low'||o.qualityPreset==='medium'?o.qualityPreset:'high',reducedMotion:o.reducedMotion===true}}; }
export function migrateSave(raw:unknown,f=createDefaultProfile()):PlayerProfile { if(!rec(raw))return f; const version=num(raw.version,1); if(version===SAVE_VERSION)return normalize(raw.profile,f); if(version===1){const source=rec(raw.profile)?{...raw.profile}:{...raw}; if(!rec(source.progression))source.progression={xp:num(source.xp)}; if(rec(source.settings)&&source.settings.controlScheme==='hold')source.settings={...source.settings,controlScheme:'charge'}; return normalize(source,f);} return f; }
export class SaveManager { constructor(private storage:StorageLike|null=typeof localStorage==='undefined'?null:localStorage,private key=DEFAULT_SAVE_KEY){} load():PlayerProfile { const f=createDefaultProfile(); if(!this.storage)return f; try{const raw=this.storage.getItem(this.key);return raw?migrateSave(JSON.parse(raw),f):f}catch{return f} } save(profile:PlayerProfile):boolean { if(!this.storage)return false; try{this.storage.setItem(this.key,JSON.stringify({version:SAVE_VERSION,profile:normalize(profile,createDefaultProfile(new Date(),profile.id))}));return true}catch{return false} } reset():PlayerProfile { try{this.storage?.removeItem(this.key)}catch{} return createDefaultProfile(); } }
EOF
